  Lemma ph_Dbad : forall regs m (w : Z),
    (20000 < w < 2 ^ 64)%Z -> getr regs 10 = Z_to_bv 64 w -> getr regs 13 = Z_to_bv 64 20001 ->
    rdn SEGS m (Z_to_bv 64 0x38470) 8 = Some (Z_to_le_bytes 8 0x394e0) -> rdn SEGS m (Z_to_bv 64 0x394e0) 4 = Some (Z_to_le_bytes 4 3) ->
    exists regs',
      msteps SEGS (mkst regs (0x192e4 : word) m rom) (mkst regs' (0x17bd8 : word) m rom)
      /\ getr regs' 10 = Z_to_bv 64 0x11fe9 /\ getr regs' 11 = Z_to_bv 64 0x10fdf /\ getr regs' 1 = Z_to_bv 64 0x1933c
      /\ regs_agree (fun r => In r [1; 10; 11]%list) regs regs'.
Proof.
