  Lemma ph_Ebad : forall regs m (h : Z),
    (20000 < h < 2 ^ 64)%Z -> getr regs 11 = Z_to_bv 64 h -> getr regs 13 = Z_to_bv 64 20001 ->
    rdn SEGS m (Z_to_bv 64 0x38470) 8 = Some (Z_to_le_bytes 8 0x394e0) -> rdn SEGS m (Z_to_bv 64 0x394e0) 4 = Some (Z_to_le_bytes 4 3) ->
    exists regs',
      msteps SEGS (mkst regs (0x19310 : word) m rom) (mkst regs' (0x17bd8 : word) m rom)
      /\ getr regs' 10 = Z_to_bv 64 0x116e8 /\ getr regs' 11 = Z_to_bv 64 0x10fdf /\ getr regs' 1 = Z_to_bv 64 0x1933c
      /\ regs_agree (fun r => In r [1; 10; 11]%list) regs regs'.
Proof.
